import clsx from 'clsx';
import React, { useEffect, useRef, useState } from 'react';

import { BookDoc } from '@/libs/document';
import { useReaderStore } from '@/store/readerStore';
import { useSidebarStore } from '@/store/sidebarStore';
import { useBookDataStore } from '@/store/bookDataStore';
import { useSettingsStore } from '@/store/settingsStore';
import TOCView from './TOCView';
import BooknoteView from './BooknoteView';
import TabNavigation from './TabNavigation';
import ChatHistoryView from './ChatHistoryView';

// The tab body is a clip-only, height-bound container (overflow-hidden) whose
// children self-scroll: TOCView and BooknoteView wire their own OverlayScrollbars
// over their Virtuoso scroller, and ChatHistoryView scrolls itself. Previously a
// second (outer) OverlayScrollbarsComponent wrapped this body, so a second
// vertical scrollbar rendered on top of the view's own one — the "two side
// progress bars" seen in the embed (#reader-double-scrollbar).
const SidebarContent: React.FC<{
  bookDoc: BookDoc;
  sideBarBookKey: string;
}> = ({ bookDoc, sideBarBookKey }) => {
  const { setHoveredBookKey } = useReaderStore();
  const { setSideBarVisible, setSearchBarVisible } = useSidebarStore();
  const { getConfig, setConfig } = useBookDataStore();
  const { settings } = useSettingsStore();
  const config = getConfig(sideBarBookKey);
  const [activeTab, setActiveTab] = useState(config?.viewSettings?.sideBarTab || 'toc');
  const [fade, setFade] = useState(false);
  const [targetTab, setTargetTab] = useState(activeTab);
  const transitionTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const isMobile = window.innerWidth < 640 || window.innerHeight < 640;
  const aiEnabled = settings?.aiSettings?.enabled ?? false;

  const configuredTab = config?.viewSettings?.sideBarTab || 'toc';
  useEffect(() => {
    if (transitionTimeoutRef.current) clearTimeout(transitionTimeoutRef.current);
    transitionTimeoutRef.current = null;
    setActiveTab(configuredTab);
    setTargetTab(configuredTab);
    setFade(false);
    return () => {
      if (transitionTimeoutRef.current) clearTimeout(transitionTimeoutRef.current);
    };
  }, [sideBarBookKey, configuredTab]);

  // reset to toc if history tab was active but AI is now disabled
  useEffect(() => {
    if ((activeTab === 'history' || targetTab === 'history') && !aiEnabled) {
      if (transitionTimeoutRef.current) clearTimeout(transitionTimeoutRef.current);
      transitionTimeoutRef.current = null;
      setActiveTab('toc');
      setTargetTab('toc');
      setFade(false);
    }
  }, [aiEnabled, activeTab, targetTab]);

  const handleTabChange = (tab: string) => {
    if (activeTab === tab) {
      if (isMobile) {
        setHoveredBookKey(sideBarBookKey);
        setSideBarVisible(false);
      }
      return;
    }

    // The header search icon is contextual (annotation search vs in-book
    // search), so an open search bar never survives a tab switch.
    setSearchBarVisible(false);
    if (transitionTimeoutRef.current) clearTimeout(transitionTimeoutRef.current);
    setFade(true);
    setActiveTab(tab);
    transitionTimeoutRef.current = setTimeout(() => {
      transitionTimeoutRef.current = null;
      setTargetTab(tab);
      setFade(false);
      const latestConfig = getConfig(sideBarBookKey);
      if (latestConfig) {
        setConfig(sideBarBookKey, {
          viewSettings: { ...latestConfig.viewSettings, sideBarTab: tab },
        });
      }
    }, 300);
  };

  return (
    <>
      <div
        className={clsx(
          'sidebar-content flex h-full min-h-0 grow flex-col shadow-inner',
          'font-sans text-base font-normal sm:text-sm',
        )}
      >
        {targetTab === 'history' ? (
          <ChatHistoryView bookKey={sideBarBookKey} />
        ) : (
          <div
            className={clsx(
              'scroll-container min-h-0 flex-1 overflow-hidden transition-opacity duration-300 ease-in-out',
              {
                'opacity-0': fade,
                'opacity-100': !fade,
              },
            )}
          >
            {targetTab === 'toc' && (bookDoc.toc || bookDoc.getPageThumbnail) && (
              <TOCView toc={bookDoc.toc ?? []} bookDoc={bookDoc} bookKey={sideBarBookKey} />
            )}
            {targetTab === 'annotations' && (
              <BooknoteView type='annotation' toc={bookDoc.toc ?? []} bookKey={sideBarBookKey} />
            )}
            {targetTab === 'bookmarks' && (
              <BooknoteView type='bookmark' toc={bookDoc.toc ?? []} bookKey={sideBarBookKey} />
            )}
          </div>
        )}
      </div>
      <div
        className='shrink-0'
        style={
          {
            // paddingBottom: 'calc(env(safe-area-inset-bottom, 0px) / 2)',
          }
        }
      >
        <TabNavigation activeTab={activeTab} onTabChange={handleTabChange} />
      </div>
    </>
  );
};

export default SidebarContent;
